-- Event-specific aggressor, rather than a not-yet-selected victim.
UPDATE creature_ai_scripts SET action1_param2=6 WHERE id IN(233801,3169101) AND event_type=4 AND action1_type=54 AND action1_param2=1;
UPDATE creature_ai_scripts SET action1_param2=6,action2_param2=6,action3_param2=6 WHERE id=690901 AND event_type=4 AND action1_type=12 AND action1_param1=6911 AND action1_param2=1 AND action2_type=12 AND action2_param1=6911 AND action2_param2=1 AND action3_type=12 AND action3_param1=6911 AND action3_param2=1;
-- A pet kill must summon the Freed Crusader for its beneficiary, not the pet.
UPDATE creature_ai_scripts SET action1_param2=7 WHERE id=3027302 AND creature_id=30273 AND event_type=6 AND action1_type=11 AND action1_param1=56515 AND action1_param2=6 AND action1_param3=1;


-- Optional scene participant recheck at action time.
UPDATE dbscripts_on_creature_movement SET priority=1 WHERE id=2131401 AND delay=4000 AND priority=0 AND command=1 AND buddy_entry=19740 AND search_radius=10;
INSERT INTO dbscripts_on_creature_movement(id,delay,priority,command,datalong,datalong2,comments)
SELECT 2131401,4000,0,31,19740,10,'ManTech: skip delayed scene if participant is no longer nearby'
WHERE EXISTS(SELECT 1 FROM dbscripts_on_creature_movement WHERE id=2131401 AND delay=4000 AND priority=1 AND command=1 AND buddy_entry=19740 AND search_radius=10)
AND NOT EXISTS(SELECT 1 FROM dbscripts_on_creature_movement WHERE id=2131401 AND delay=4000 AND priority=0 AND command=31 AND datalong=19740 AND datalong2=10);


-- Optional scene participant recheck at action time.
UPDATE dbscripts_on_go_template_use SET priority=1 WHERE id=170562 AND delay=1000 AND priority=0 AND command=0 AND buddy_entry=9023 AND search_radius=20;
INSERT INTO dbscripts_on_go_template_use(id,delay,priority,command,datalong,datalong2,comments)
SELECT 170562,1000,0,31,9023,20,'ManTech: skip delayed scene if participant is no longer nearby'
WHERE EXISTS(SELECT 1 FROM dbscripts_on_go_template_use WHERE id=170562 AND delay=1000 AND priority=1 AND command=0 AND buddy_entry=9023 AND search_radius=20)
AND NOT EXISTS(SELECT 1 FROM dbscripts_on_go_template_use WHERE id=170562 AND delay=1000 AND priority=0 AND command=31 AND datalong=9023 AND datalong2=20);

